from datetime import date
from typing import List, Optional
from pydantic import BaseModel, Field


class SpendingInsight(BaseModel):
    """Specific insight or observation generated by Gemini."""

    type: str = Field(description="Type: 'saving_opportunity', 'warning', 'anomaly', or 'positive'.")
    title: str = Field(description="Short title for the insight.")
    message: str = Field(description="Detailed explanation.")
    potential_monthly_savings: Optional[float] = Field(
        default=None, description="Estimated monthly savings in currency if implemented."
    )


class FinancialAdviceResponse(BaseModel):
    """Structured response for financial advice and conversational queries."""

    summary_headline: str = Field(description="A concise summary headline of the spending analysis.")
    answer: str = Field(description="Comprehensive and friendly financial advisor advice.")
    insights: List[SpendingInsight] = Field(
        default_factory=list, description="Specific categorized insights."
    )
    actionable_recommendations: List[str] = Field(
        default_factory=list, description="Bullet points of concrete next steps the user can take."
    )
    top_spending_category: Optional[str] = Field(
        default=None, description="The category with the largest spend in the analyzed period."
    )


class AdvisorChatRequest(BaseModel):
    """Incoming user query to the AI financial advisor."""

    question: str = Field(description="Natural language question or request regarding finances.")
    start_date: Optional[date] = None
    end_date: Optional[date] = None
    category: Optional[str] = None


class BudgetAuditResponse(BaseModel):
    """AI health check and anomaly scan of user's spending habits."""

    financial_health_score: int = Field(
        description="Score from 0 to 100 assessing spending discipline and budget alignment."
    )
    month_analyzed: str = Field(description="Target month (YYYY-MM).")
    summary: str = Field(description="Overall audit narrative.")
    overspent_categories: List[str] = Field(
        default_factory=list, description="Categories exceeding typical thresholds or budgets."
    )
    anomalies_detected: List[str] = Field(
        default_factory=list, description="Unusual transaction spikes, subscriptions, or double charges."
    )
    recommended_actions: List[str] = Field(
        default_factory=list, description="Targeted budget corrections."
    )
